                                                <!-- <td style="white-space: pre">{{ unit2.expression.replaceAll(";", "\n") }}
                                                </td>
                                                <td>{{ parsesum(unit2.expression) }}</td> -->

                                                <td v-if="unit2.expression" style="white-space: pre">{{
                                                    unit2.expression.replaceAll(";", "\n") }}</td>
                                                <td v-if="unit2.expression">{{ parsesum(unit2.expression) }}</td>


