<script>
import { loadProjects } from '../utils/contactUtils.js';

import powerSlide from './powerSlide.vue'

export default {
    components: {
        powerSlide
    },
    props: {
        projectName: {
            type: String,
            required: true,
        },
    },
    data() {
        return {
            projects: [],
            expanded: false, // State to toggle extra fields
            isImageModalVisible: false,
            clickedImageUrl: '',
            label1: "Formula",
            label2: "Net Price",
            label3: ""

        };
    },
    async mounted() {
        await this.loadProjectsData(this.projectName);
    },


    methods: {
        parsesum(ss) {
            try {
                // Reset error state
                this.error = null;

                // Split the expression into variable assignments and computation
                if (!(ss)) return;
                const parts = ss.split(';');
                const assignments = parts[0].split(',');
                const computation = parts[1].trim();

                // Object to store our variables
                const variables = {};

                // Parse assignments
                //    this.assignments.forEach((assignment, index) => {
                assignments.forEach(assignment => {
                    const [variable, value] = assignment.split('=').map(s => s.trim());

                    // Parse the value based on format

                    if (value.toLowerCase().endsWith('k')) {
                        // Handle 'k' notation (thousands)
                        variables[variable] = parseFloat(value.toLowerCase().replace('k', '')) * 1000;
                    } else if (value.endsWith('%')) {
                        // Handle percentage
                        variables[variable] = parseFloat(value.replace('%', '')) / 100;
                    } else {
                        // Handle regular numbers
                        variables[variable] = parseFloat(value);
                    }
                });

                // Replace variables in computation with their values
                let computationString = computation.split(":")[1];
                for (const [variable, value] of Object.entries(variables)) {
                    computationString = computationString.replaceAll(variable, value);
                }

                // Evaluate the computation
                // eslint-disable-next-line no-eval
                this.result = eval(computationString);

                // Format the result
                this.result = new Intl.NumberFormat('en-US', {
                    style: 'currency',
                    currency: 'USD'
                }).format(this.result);

                this.result = computation.split(":")[0] + " " + this.result;
                // this.label1 = this.projects[0].formulaHeader.split(",")[0];
                // this.label2 = this.projects[0].formulaHeader.split(",")[1];

                if (this.projects[0].formulaHeader.split(",").length > 2)
                    this.label3 = this.projects[0].formulaHeader.split(",")[2];

                return this.result;
            } catch (err) {
                this.error = `Failed to parse expression: ${err.message}`;
                alert(err.message);
                this.result = null;
            }
        },
        // Method to parse a new expression




        async loadProjectsData(projectFilter) {
            try {
                const projects = await loadProjects(projectFilter);
                console.log('Loaded projects:', projects);
                this.projects = projects;
            } catch (error) {
                console.error('Error loading projects:', error);
            }
        },
        showImageModal(url) {

            this.clickedImageUrl = url;
            this.isImageModalVisible = true;

        },
        closeImageModal() {
            this.isImageModalVisible = false;
        },
        toggleExpanded() {
            this.expanded = !this.expanded;
        },
        editProject(row) {
            console.log('Editing project:', row);
            // Implement your edit logic here
        },
        deleteProject(row) {
            console.log('Deleting project:', row);
            // Implement your delete logic here
        },
    },
};
</script>

